package cn.local.rainreminder;
import android.content.*;
public class AgendaReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){try{String batch=i.getStringExtra("batch");if(batch==null)Agenda.deliver(c,i,System.currentTimeMillis());else{org.json.JSONArray items=new org.json.JSONArray(batch);for(int n=0;n<items.length();n++){org.json.JSONObject e=items.getJSONObject(n);Intent one=new Intent(c,AgendaReceiver.class).putExtra("id",e.getString("id")).putExtra("kind",e.getString("kind")).putExtra("start",e.getLong("start")).putExtra("at",e.getLong("at")).putExtra("key",e.getString("key"));Agenda.deliver(c,one,System.currentTimeMillis());}}}catch(Exception ignored){}finally{Agenda.schedule(c);}}}
